export interface CompleteAiGuide {
  number: number; slug: string; module: string; title: string; summary: string
  example: string; application: string; limitation: string
  term: [string, string]
  steps: [string, string][]
  checks: [string, string, string, string, string][]
  task: string; hint: string; solution: string
}

// Original ilearnai teaching guides surrounding the attributed Microsoft readings.
// Each numerical example is intentionally small enough to inspect without a model.
export const completeAiGuides: CompleteAiGuide[] = [
  { number: 1, slug: 'ai-history-and-approaches', module: 'ideas-and-reasoning', title: 'AI history: rules, learning, and generation',
    summary: 'Distinguish a hand-written rule, a learned prediction, and generated content before choosing an approach.',
    example: 'Imagine sorting customer messages. A rule can send every message containing “invoice” to billing. A learned classifier can use labelled examples to recognise varied wording. A language model can draft a reply. These are different jobs, even when one application combines them.',
    application: 'A service manager can begin with the outcome: route the message correctly, find an approved answer, or draft a response for review. The business requirement should determine the method.',
    limitation: 'A convincing answer or a successful conversation does not establish general intelligence, understanding, or correctness. Historical benchmarks measure specific behaviours under particular conditions.',
    term: ['symbolic-ai', 'AI that represents knowledge with explicit symbols and rules, then reasons over them.'],
    steps: [['Work problem', 'An incoming message needs a destination and possibly an answer.'], ['Choose a method', 'Rules use explicit conditions; a classifier learns patterns from examples.'], ['Inspect the output', 'Routing chooses a category. Generation creates a proposed response.'], ['Test the outcome', 'Measure routing errors and unsupported claims separately.']],
    checks: [['Which task needs a generated output?', 'Drafting a new reply for review', 'Checking whether a fixed keyword occurs', 'Comparing an amount with a fixed threshold', 'Generation produces proposed content. A deterministic rule can handle the other two tasks.'], ['A chatbot passes a conversation test. What follows?', 'It performed well under that test’s conditions', 'Every factual statement it makes is correct', 'It can safely perform every office task', 'A benchmark result is evidence about that benchmark, not an unlimited capability guarantee.']],
    task: 'For an expense process, assign a method to checking an amount limit, predicting unusual claims, and drafting a clarification message. Name one evaluation measure for each.', hint: 'Separate a fixed condition, a pattern learned from examples, and an output written in natural language.', solution: 'Amount limit: explicit rule; test boundary values. Unusual claims: prediction; measure false alerts and missed confirmed cases. Clarification: generation; check source support, tone, and required information.' },
  { number: 2, slug: 'knowledge-and-expert-systems', module: 'ideas-and-reasoning', title: 'Knowledge, expert systems, and ontologies',
    summary: 'Trace explicit facts through rules and explain the difference between missing knowledge and a false statement.',
    example: 'A fictional equipment desk knows that device P7 has power and its network test failed. Rule A says: if power is present and the network test fails, check the cable. Rule B says: if a cable check fails, escalate the connection. The second conclusion needs a new fact; the first rule cannot invent it.',
    application: 'Use explicit rules for stable policy conditions and repeatable troubleshooting. An ontology can connect equipment, locations, owners, and relationships so different systems use the same meanings.',
    limitation: 'Rules only express the knowledge encoded in them. Conflicting rules need priorities or resolution. Unknown facts must not silently become false facts or invented evidence.',
    term: ['ontology', 'A defined set of concepts and relationships used to describe a domain consistently.'],
    steps: [['Facts', 'Power is present; the network test failed.'], ['Match a rule', 'Both conditions of the cable-check rule are satisfied.'], ['Infer an action', 'Recommend checking the cable; do not claim the cable is faulty yet.'], ['Add evidence', 'A new test result can enable another rule or stop the chain.']],
    checks: [['Why can the system recommend a cable check?', 'Known facts satisfy the rule’s conditions', 'Every network failure proves cable damage', 'The most recent rule must always run', 'Forward inference starts with facts and applies rules whose conditions match.'], ['No cable-test result is recorded. What is its status?', 'Unknown', 'Failed', 'Passed', 'Absence of a result supplies neither a pass nor a failure.']],
    task: 'Write two rules for a document checklist. Use the facts “form present”, “identity evidence present”, and “review completed”. Show a case where a rule cannot yet run.', hint: 'Separate “ready for review” from “approved”; a checklist cannot supply the reviewer’s decision.', solution: 'If form present AND identity evidence present: ready for review. If ready for review AND review completed: record the review result. With no identity evidence fact, readiness remains unresolved; do not infer approval.' },
  { number: 3, slug: 'perceptron', module: 'neural-networks', title: 'A perceptron: one learned boundary',
    summary: 'Compute a weighted score, apply a threshold, and identify a boundary that one perceptron cannot learn.',
    example: 'A toy classifier receives x1 = 1 and x2 = 2, uses weights 2 and −1, and bias 0.5. Its score is 2 × 1 − 1 × 2 + 0.5 = 0.5. If the decision rule returns 1 when the score is at least zero, the predicted class is 1.',
    application: 'This small model introduces the same input, parameter, score, and decision separation used in larger systems. It also provides a simple baseline before more complex models.',
    limitation: 'One perceptron makes a linear boundary. XOR cannot be separated by one straight line in its original two-dimensional input space.',
    term: ['perceptron', 'A classifier that computes a weighted sum and bias, then applies a threshold to choose a class.'],
    steps: [['Inputs 1 and 2', 'Inputs are observed values, not trainable parameters.'], ['Weighted score', '2 × 1 + (−1) × 2 + 0.5 = 0.5.'], ['Threshold at 0', 'Because 0.5 is at least zero, return class 1.'], ['Compare with label', 'During training, a wrong decision can trigger a weight update.']],
    checks: [['What is the score in the worked example?', '0.5', '2.5', '−0.5', 'Multiply both inputs by their weights, add them, then add the bias once.'], ['What requires more than one linear boundary in the original input space?', 'XOR', 'Separating points to the left and right of a straight line', 'A single amount threshold', 'XOR has opposite corners in each class; a single line cannot separate them.']],
    task: 'Use the same weights and bias for inputs x1 = 0, x2 = 1. Calculate the score and class. Then change only the bias to 2.', hint: 'Calculate the score before applying the threshold.', solution: 'With bias 0.5: score = 0 − 1 + 0.5 = −0.5, class 0. With bias 2: score = 1, class 1. A bias moves the boundary without changing input weights.' },
  { number: 4, slug: 'mlp-and-backpropagation', module: 'neural-networks', title: 'Layers, loss, and backpropagation',
    summary: 'Follow a forward pass, measure its error, and trace how gradients guide a parameter update.',
    example: 'Let a tiny model predict y = w × x with x = 2, target 6, and w = 1. The prediction is 2 and squared loss is (2 − 6)² = 16. The derivative with respect to w is 2 × (2 − 6) × 2 = −16. With learning rate 0.1, the new weight is 2.6 and the new loss is 0.64.',
    application: 'Architects and builders use the same cycle when training larger networks: compute outputs, measure a task-specific loss, propagate derivatives, then update parameters.',
    limitation: 'Backpropagation computes gradients; an optimizer uses them to update parameters. A lower training loss does not by itself demonstrate performance on new examples.',
    term: ['backpropagation', 'An application of the chain rule that computes how a loss changes with each parameter in a network.'],
    steps: [['Forward: 2', 'Multiply weight 1 by input 2 to predict 2.'], ['Loss: 16', 'Compare prediction 2 with target 6 using squared error.'], ['Gradient: −16', 'Differentiate the loss through the multiplication.'], ['Update: 2.6', 'Subtract 0.1 × (−16) from the old weight 1.']],
    checks: [['Which value does backpropagation produce?', 'Derivatives of the loss with respect to parameters', 'A guarantee of the best possible model', 'New labelled training records', 'Gradients describe local sensitivity; they are inputs to an optimizer.'], ['What happens after the worked update?', 'The prediction becomes 5.2 and loss becomes 0.64', 'The prediction remains 2', 'The loss must become exactly zero', 'The new prediction is 2.6 × 2 = 5.2; its error is −0.8.']],
    task: 'Repeat the worked update with learning rate 0.01. Compare the new loss with learning rate 0.1.', hint: 'New weight = old weight − rate × gradient.', solution: 'New weight = 1.16; prediction = 2.32; loss = (2.32 − 6)² = 13.5424. It improves less in this step. This does not imply that larger rates are always better.' },
  { number: 5, slug: 'frameworks-and-overfitting', module: 'neural-networks', title: 'PyTorch, TensorFlow, and overfitting',
    summary: 'Recognise a training loop in both frameworks and use validation data to detect memorisation.',
    example: 'Across three epochs, training loss is 0.8, 0.4, 0.1 while validation loss is 0.9, 0.5, 0.7. Epoch three fits the training records better but performs worse on validation. A checkpoint from epoch two is a better candidate under this validation measure.',
    application: 'Delivery teams should record dataset splits, preprocessing, model settings, and evaluation results. PyTorch and TensorFlow both support tensors, automatic differentiation, and trainable layers; their APIs and execution conventions differ.',
    limitation: 'Repeatedly tuning against the test set leaks information. Use validation for selection and keep a final test set for a less biased estimate. Early stopping is one tool, not a universal cure.',
    term: ['validation-set', 'Examples held out from parameter fitting and used to choose model settings or checkpoints.'],
    steps: [['Split the data', 'Keep fitting, validation, and final testing roles distinct.'], ['Fit parameters', 'Training loss improves from 0.8 to 0.1.'], ['Check validation', 'Validation improves to 0.5, then worsens to 0.7.'], ['Choose checkpoint', 'Select epoch two using validation; evaluate the final choice once on test data.']],
    checks: [['Which checkpoint has the best shown validation loss?', 'Epoch two', 'Epoch three', 'Epoch one', '0.5 is lower than both 0.9 and 0.7; training loss alone gives a different answer.'], ['What does a framework’s automatic differentiation remove?', 'The need to hand-derive every parameter gradient', 'The need to define a useful loss', 'The need for independent evaluation', 'A framework computes derivatives of the defined computation, not the appropriateness of the task or data.']],
    task: 'Make a three-column experiment log: epoch, training loss, validation loss. Explain which checkpoint you would keep and what data you would evaluate next.', hint: 'The final test set must not become another tuning set.', solution: 'Keep epoch two under the stated criterion. Freeze the selection and evaluate on held-out test examples. Also inspect per-group and difficult-case errors rather than relying only on one average.' },
  { number: 6, slug: 'computer-vision-and-opencv', module: 'computer-vision', title: 'Computer vision: pixels, channels, and OpenCV',
    summary: 'Read an image as a numerical array, distinguish RGB from BGR, and explain preprocessing before inference.',
    example: 'A color photograph that is 320 pixels wide and 200 high often has array shape (200, 320, 3): rows, columns, channels. A red pixel is (255, 0, 0) in RGB but (0, 0, 255) in BGR. Swapping channels changes the displayed color; it does not rotate or resize the image.',
    application: 'An inspection team can align photographs, standardise lighting, and flag changed regions before using a classifier. A fixed-camera frame difference can reveal motion without a neural network.',
    limitation: 'Preprocessing cannot recover information that was never captured. Camera movement, shadows, and lighting changes can produce motion-like differences. Verify conventions at each library boundary.',
    term: ['color-channel', 'One numerical component of a pixel, such as its red, green, or blue intensity.'],
    steps: [['Image file', 'Decode the photograph into rows, columns, and channels.'], ['BGR → RGB', 'Reorder channel values before displaying an OpenCV image with an RGB viewer.'], ['Prepare pixels', 'Resize and normalise consistently with the model’s training process.'], ['Inspect changes', 'A changed region needs interpretation; a pixel difference is not a confirmed defect.']],
    checks: [['What is the usual array shape for this color image?', '(200, 320, 3)', '(320, 200)', '(3, 3, 3)', 'For this convention, height is first, width second, and three channels last. Other frameworks may use different layouts.'], ['A fixed-camera difference image changes after the lights switch on. What can you conclude?', 'The pixels changed; the cause needs checking', 'An object definitely moved', 'The camera identified a defective product', 'Frame difference measures intensity changes and does not establish the cause.']],
    task: 'Convert BGR pixel (10, 20, 240) to RGB. For grayscale frames [10, 20, 30] and [10, 25, 10], calculate absolute differences and mark values above 10.', hint: 'Reverse the red and blue positions. For motion, use abs(new − old).', solution: 'RGB = (240, 20, 10). Absolute differences = [0, 5, 20]. With a strict threshold above 10, only the third position is marked.' },
  { number: 7, slug: 'convolutional-neural-networks', module: 'computer-vision', title: 'Convolutional networks: local patterns to categories',
    summary: 'Compute one convolution response and connect feature maps, pooling, and classification.',
    example: 'Take a 3 × 3 patch whose rows are [0, 0, 9]. Apply a vertical-edge filter whose rows are [−1, 0, 1]. Elementwise multiplication and addition gives 27. The same filter slides across the image, producing a map of responses rather than one overall class.',
    application: 'A factory image classifier can reuse learned local patterns such as edges and textures at different locations. Deeper layers combine these into more task-specific features.',
    limitation: 'A high filter response is a numerical feature, not a reliable object explanation on its own. Lighting changes, image scale, and differences from training data can still break performance.',
    term: ['convolution', 'A local weighted operation applied repeatedly across an input using shared filter weights.'],
    steps: [['Pixel patch', 'Read a small neighbourhood rather than the whole image at once.'], ['Filter response: 27', 'Multiply matching entries and add them to get one response.'], ['Feature map', 'Move the same weights across the image and optionally downsample.'], ['Class scores', 'Combine features and evaluate predictions on unseen images.']],
    checks: [['Why are convolution weights shared?', 'The same filter can detect a pattern at multiple locations', 'Every image has identical pixel values', 'No parameters need to be learned', 'Sharing reuses a local operation across positions and reduces the parameter count.'], ['What is the response for the worked patch?', '27', '9', '0', 'Each row contributes 9, so the three rows sum to 27.']],
    task: 'Reverse the worked patch so each row is [9, 0, 0]. Recalculate the response. Then apply ReLU.', hint: 'The left column has weight −1. ReLU keeps max(0, response).', solution: 'The response is −27. ReLU changes it to 0. An oppositely oriented filter could respond positively; this filter alone does not represent every edge.' },
  { number: 8, slug: 'vision-transfer-learning', module: 'computer-vision', title: 'Transfer learning: reuse features, test the new task',
    summary: 'Distinguish a frozen feature extractor from fine-tuning and design a fair evaluation for a new image task.',
    example: 'You have 300 labelled photographs of three packaging types. A pretrained image network converts each picture into a feature vector. First freeze its parameters and train a new three-class output layer. Only after establishing a baseline might you unfreeze later layers and fine-tune with a smaller learning rate.',
    application: 'This approach can make a smaller image project practical when collecting a huge labelled dataset is unrealistic. It is useful only if the transferred representation is relevant to the new images.',
    limitation: 'Pretraining does not guarantee transfer. Different cameras, backgrounds, and product batches can cause misleading scores. Split by item or batch when related images would otherwise leak between sets.',
    term: ['transfer-learning', 'Reusing knowledge learned on one task or dataset to help with another, often through pretrained parameters.'],
    steps: [['New images', 'Keep related photographs together when creating train and test splits.'], ['Frozen backbone', 'Extract features without updating the pretrained weights.'], ['New output layer', 'Learn three output scores for the new packaging labels.'], ['Evaluate and adapt', 'Compare with a baseline before deciding whether to fine-tune more layers.']],
    checks: [['Which parameters change when the backbone is frozen?', 'Only the trainable new output layer', 'Every parameter in the backbone', 'None, including the new output layer', 'Frozen backbone parameters are excluded from updates; the new head still learns.'], ['Why keep photographs of one item in the same split?', 'To reduce leakage from highly related examples', 'To make the test set easier', 'To eliminate the need for labels', 'Near-duplicate item images can make held-out performance look better than it is.']],
    task: 'Plan a comparison between a frozen-backbone model and a fine-tuned model. Name two factors to keep constant.', hint: 'A comparison is easier to interpret when the data split and evaluation measure match.', solution: 'Keep train/validation/test examples and the success measure constant. Record preprocessing, learning rates, and which layers are trainable. Compare held-out error and the cost of training, not only fitting accuracy.' },
  { number: 9, slug: 'autoencoders-and-vaes', module: 'computer-vision', title: 'Autoencoders and variational autoencoders',
    summary: 'Explain reconstruction, a bottleneck, and the additional distribution constraint used by a VAE.',
    example: 'An encoder maps a four-value signal [2, 2, 8, 8] to a shorter representation. A decoder reconstructs [3, 3, 7, 7]. Each squared difference is 1, so mean squared reconstruction error is 1. A VAE also regularises its latent distribution, trading reconstruction quality against a more structured space for sampling.',
    application: 'Autoencoders can support compression, denoising, or exploratory anomaly detection. A quality team might inspect unusually large reconstruction errors as leads, then verify what caused them.',
    limitation: 'High reconstruction error does not prove a fault, and low error does not certify normality. A model can reconstruct an unfamiliar or undesirable input well. A VAE is not simply a smaller ordinary autoencoder.',
    term: ['latent-representation', 'An internal representation learned to capture features useful for a model’s objective.'],
    steps: [['Input signal', 'The example has four numerical values: 2, 2, 8, 8.'], ['Encode', 'Compress or transform the signal into a latent representation.'], ['Decode', 'Reconstruct an approximation: 3, 3, 7, 7.'], ['Measure and constrain', 'Reconstruction error is 1; a VAE also penalises divergence from a chosen prior.']],
    checks: [['What is the mean squared reconstruction error here?', '1', '4', '16', 'Four squared errors of 1 sum to 4; averaging over four values gives 1.'], ['What makes a VAE objective different?', 'It includes a distribution regularisation term as well as reconstruction', 'It never reconstructs inputs', 'It guarantees perfect compression', 'The latent distribution is encouraged to follow a chosen prior, enabling a different sampling trade-off.']],
    task: 'Compare reconstruction [2, 2, 8, 8] with [0, 0, 0, 0] against the original signal. Calculate both mean squared errors.', hint: 'Square each difference, then average the four results.', solution: 'The exact reconstruction has error 0. The all-zero reconstruction has (4 + 4 + 64 + 64) / 4 = 34. Neither number alone establishes performance on new data.' },
  { number: 10, slug: 'gans-and-style-transfer', module: 'computer-vision', title: 'GANs and artistic style transfer',
    summary: 'Separate adversarial generation from transferring visual style onto an existing image.',
    example: 'A generator creates synthetic packaging textures from random inputs. A discriminator learns to distinguish generated textures from the training examples. Training alternates their updates. By contrast, a style-transfer process starts with a content image and seeks an image that preserves its structure while matching selected style statistics.',
    application: 'Design teams can explore visual alternatives, while technical teams can study how objectives shape generated outputs. Any synthetic training data needs independent checks for diversity, label validity, and distribution mismatch.',
    limitation: 'A discriminator score is not a certificate of quality or originality. A GAN can collapse to a narrow set of outputs. Style similarity does not establish permission to reuse someone else’s work.',
    term: ['mode-collapse', 'A failure in which a generative model produces too little diversity, repeating a limited set of outputs.'],
    steps: [['Random input', 'Start the generator from a sampled latent value.'], ['Generated texture', 'The generator produces a candidate image.'], ['Discriminator feedback', 'Compare real and generated examples under the training objective.'], ['Alternating updates', 'Update both networks in turn and inspect quality and diversity separately.']],
    checks: [['Which symptom suggests mode collapse?', 'Different random inputs produce very similar images', 'Every generated image has the same dimensions', 'The output is stored as a file', 'Mode collapse concerns missing output diversity, not image shape or file format.'], ['What does style transfer normally preserve?', 'Selected content structure while changing style statistics', 'An exact copy of every source pixel', 'The discriminator’s class label', 'Content and style objectives constrain different properties of the generated image.']],
    task: 'Write a review checklist for ten generated textures. Include one quality check, one diversity check, and one use-rights check.', hint: 'A pleasing single example can hide repetition or unsuitable source material.', solution: 'Quality: inspect artifacts and fit to intended use. Diversity: compare outputs from different random inputs for repetition. Rights: confirm the data and intended use are permitted; a generated result does not remove those obligations.' },
  { number: 11, slug: 'object-detection', module: 'computer-vision', title: 'Object detection and intersection over union',
    summary: 'Distinguish detection from classification and compute how well a predicted box overlaps a labelled object.',
    example: 'A parcel image contains two boxes. A classifier might return “parcel”; a detector needs a label and a rectangle for each parcel. If a predicted rectangle has area 8, the true rectangle has area 8, and their overlap has area 4, the union is 8 + 8 − 4 = 12. Intersection over union is 4 / 12, or one third.',
    application: 'Warehouses can count visible packages, and inspection teams can locate candidate defects. The useful output includes where each object is, not just whether a category appears somewhere.',
    limitation: 'Confidence and overlap are different measures. Detection metrics depend on class matching, confidence thresholds, overlap thresholds, and missed objects. Average precision is not the average of box overlaps.',
    term: ['intersection-over-union', 'The overlap area of two regions divided by the area covered by either region.'],
    steps: [['Image with objects', 'A scene can contain multiple instances and categories.'], ['Predict boxes', 'Return candidate locations, categories, and scores.'], ['Match references', 'Compare predicted and labelled objects with a stated overlap rule.'], ['Count errors', 'Track misses, duplicate detections, wrong categories, and false positives.']],
    checks: [['What is IoU for areas 8 and 8 with overlap 4?', '1/3', '1/2', '1', 'The union subtracts the shared region once: 8 + 8 − 4 = 12.'], ['What additional output does detection need beyond whole-image classification?', 'Locations of object instances', 'Only a longer category name', 'A guaranteed explanation of every pixel', 'Detection associates categories with localised objects; segmentation is a separate pixel-level task.']],
    task: 'Calculate IoU for identical boxes and for non-overlapping boxes. Explain why a high confidence score cannot replace the overlap calculation.', hint: 'Identical regions have equal intersection and union; disjoint regions have zero intersection.', solution: 'Identical boxes: IoU 1. Non-overlapping boxes: IoU 0. Confidence expresses the model’s score, while IoU compares geometry with a reference.' },
  { number: 12, slug: 'segmentation-and-unet', module: 'computer-vision', title: 'Segmentation and U-Net',
    summary: 'Explain pixel labels, encoder-decoder paths, and skip connections in a segmentation model.',
    example: 'A four-pixel reference mask is [1, 1, 0, 0] and the predicted mask is [1, 0, 1, 0]. One foreground pixel overlaps, while three pixels belong to at least one foreground mask. The foreground IoU is 1/3. This evaluates the shape more directly than a label for the whole image.',
    application: 'Segmentation can outline land cover, road areas, or surface defects. A reviewer can inspect exactly which pixels the model assigned to a region and compare them with a reference mask.',
    limitation: 'Semantic segmentation labels pixel categories; it does not necessarily distinguish separate objects of the same category. Accuracy can look high when background pixels dominate, so choose task-appropriate metrics.',
    term: ['semantic-segmentation', 'Assigning a category to each pixel so regions can be identified within an image.'],
    steps: [['Input image', 'Preserve the spatial arrangement of pixels.'], ['Encode context', 'Downsampling gathers broader contextual features.'], ['Decode detail', 'Upsampling combines coarse features with skip-connected spatial information.'], ['Pixel mask', 'Predict a label at each pixel and compare the resulting regions.']],
    checks: [['Why use skip connections in a U-Net?', 'To pass spatial detail from encoder stages to decoder stages', 'To remove the need for labelled masks', 'To turn every pixel into the same category', 'Features from corresponding scales help the decoder recover localisation detail.'], ['What is foreground IoU for the worked masks?', '1/3', '1/2', '1', 'The foreground intersection contains one pixel and the foreground union contains three.']],
    task: 'A 100-pixel image has 95 background pixels. A model predicts background everywhere. Compute accuracy and describe the missed task.', hint: 'Count correct background pixels, then consider whether any foreground was found.', solution: 'Accuracy is 95%, but the model misses every foreground pixel. Foreground recall is zero; high overall accuracy conceals failure on the region of interest.' },
  { number: 13, slug: 'bow-and-tfidf', module: 'language-and-representation', title: 'Bag of words, n-grams, and TF-IDF',
    summary: 'Build a simple text representation and explain why a rare term can be more useful than a frequent one.',
    example: 'With vocabulary [refund, delivery, late], the text “late delivery delivery” has count vector [0, 2, 1]. Bag of words ignores order. A two-word feature such as “not approved” can preserve a small piece of order. TF-IDF reduces the relative influence of terms appearing across many documents.',
    application: 'A support team can build a searchable baseline or a simple topic classifier before using large models. These representations are inexpensive, interpretable starting points for comparison.',
    limitation: 'Counts do not understand meaning or all word order. Negation, synonyms, spelling variation, and context can break naive matching. Vocabulary and IDF must be fitted on training documents only.',
    term: ['tf-idf', 'A term weight combining its frequency in a document with how uncommon it is across the document collection.'],
    steps: [['Tokenise text', 'Split text consistently and choose any normalisation rules.'], ['Count vocabulary', 'The example gives refund 0, delivery 2, late 1.'], ['Weight terms', 'Terms common across documents receive less distinctive weight.'], ['Compare documents', 'Use the vectors for retrieval or a baseline classifier, then evaluate errors.']],
    checks: [['What does ordinary bag of words discard?', 'The ordering of words', 'Every word count', 'The chosen vocabulary', 'It aggregates counts by vocabulary term regardless of where each occurrence appeared.'], ['Why fit IDF on training data only?', 'To avoid using held-out collection information during model fitting', 'Because test documents cannot contain words', 'To guarantee every rare word is relevant', 'Even preprocessing statistics can leak information from held-out examples.']],
    task: 'With vocabulary [red, blue, car], encode “red car red” and “blue car”. Give one pair of phrases that bag of words cannot distinguish.', hint: 'Use one count per vocabulary item. Changing only word order leaves counts unchanged.', solution: 'Vectors: [2, 0, 1] and [0, 1, 1]. “Dogs chase cats” and “cats chase dogs” have equal word counts but different meanings.' },
  { number: 14, slug: 'word2vec-and-glove', module: 'language-and-representation', title: 'Word2Vec, GloVe, and embedding similarity',
    summary: 'Explain how distributional context produces vectors and distinguish static from contextual word representations.',
    example: 'Suppose two normalized word vectors point in nearly the same direction. Their cosine similarity is high, suggesting similar patterns under the training objective. But the static vector for “bank” is shared between a river-bank sentence and a banking sentence; a contextual model can produce different representations for those occurrences.',
    application: 'Embeddings can help find related language across varied wording. A search team should still test actual retrieval relevance rather than assuming geometric similarity equals a correct answer.',
    limitation: 'Distributional similarity can reflect biased or irrelevant patterns. Static embeddings mix different senses of a word. A vector analogy is a property to investigate, not proof of human-like reasoning.',
    term: ['word-embedding', 'A numerical vector for a word, learned so aspects of language use are reflected in its position or direction.'],
    steps: [['Context examples', 'Collect which words occur near each other in training text.'], ['Training objective', 'Word2Vec predicts local context relationships; GloVe uses co-occurrence statistics.'], ['Vector space', 'Each vocabulary word receives learned numerical coordinates.'], ['Test a use case', 'Compare neighbours, ambiguity, bias, and retrieval relevance on held-out examples.']],
    checks: [['Why is “bank” difficult for a static embedding?', 'One vector must represent multiple uses of the same word', 'It has too few letters to tokenize', 'Cosine similarity requires every word to be a place', 'A contextual embedding can depend on the surrounding sentence; a static lookup cannot.'], ['What does high cosine similarity directly describe?', 'Alignment between two vectors', 'A verified factual relationship', 'A legal permission to use the text', 'Similarity is a geometric measure whose usefulness depends on training and the task.']],
    task: 'Compute the dot product of [1, 0] with [1, 0], [0, 1], and [−1, 0]. For these unit vectors, interpret the cosine values.', hint: 'Multiply matching coordinates and add them. Each vector already has length one.', solution: 'Cosines are 1, 0, and −1: aligned, perpendicular, and opposite. This is geometry; what those directions mean depends on the learned representation.' },
  { number: 15, slug: 'training-language-embeddings', module: 'language-and-representation', title: 'Language modelling and training embeddings',
    summary: 'Build context-target examples and distinguish CBOW from skip-gram training.',
    example: 'In “the small cat sleeps”, a context window around “cat” might contain “small” and “sleeps”. CBOW predicts the centre word from its neighbours. Skip-gram predicts neighbouring words from the centre. The resulting vectors are parameters learned to help solve that prediction task.',
    application: 'This makes embedding learning concrete: the training signal comes from language context rather than a hand-written similarity table. It is also a stepping stone toward larger language-model objectives.',
    limitation: 'A context window is a design choice. Frequent words, vocabulary limits, and sampling decisions affect what is learned. A short corpus cannot produce a general language representation.',
    term: ['cbow', 'Continuous bag of words: an objective that predicts a centre word from representations of its surrounding words.'],
    steps: [['Token sequence', 'Choose a window within a sequence of words.'], ['Context and target', 'Neighbours small and sleeps become inputs; cat becomes the target.'], ['Predict target', 'Convert the combined context representation into vocabulary scores.'], ['Update embeddings', 'Use the prediction error to change the embedding parameters.']],
    checks: [['In CBOW, what is predicted from nearby words?', 'The centre word', 'Only the document file name', 'The exact training date', 'CBOW aggregates context to predict a target; skip-gram reverses that direction.'], ['Why do the embeddings change during training?', 'They are parameters affecting prediction loss', 'Each word is assigned an unchangeable random meaning', 'The vocabulary automatically becomes sorted by truth', 'Gradients update useful representations for the objective; they do not assign verified meanings.']],
    task: 'For “we learn useful ideas today”, use a one-word window on each side. Write the CBOW example centred on “useful”, then the two skip-gram pairs.', hint: 'Reverse which side is input and which side is target.', solution: 'CBOW: [learn, ideas] → useful. Skip-gram: useful → learn and useful → ideas. These examples come from one local window, not the entire sentence meaning.' },
  { number: 16, slug: 'recurrent-networks-and-lstm', module: 'language-and-representation', title: 'Recurrent networks and LSTM memory',
    summary: 'Trace a recurrent state through a sequence and explain why gated memory helps with long dependencies.',
    example: 'For a toy recurrence h = 0.5 × previous_h + input, start at h = 0 and read [2, 0, 0]. The states are 2, 1, and 0.5. Earlier information fades. An LSTM uses learned gates to control what enters, remains in, and leaves a memory state rather than applying this fixed decay.',
    application: 'Sequence models apply to text, demand readings, and sensor signals. The same values in a different order can describe a different situation, so a model must handle temporal context deliberately.',
    limitation: 'Gates can help preserve information but do not guarantee useful long-term memory. A bidirectional model uses future context, which may be unavailable in a live prediction task.',
    term: ['recurrent-state', 'An internal value updated at each sequence step so later predictions can depend on earlier inputs.'],
    steps: [['Start state 0', 'Before the sequence, initialise the recurrent state.'], ['Read 2: state 2', '0.5 × 0 + 2 = 2.'], ['Read 0: state 1', 'The previous contribution decays by half.'], ['Read 0: state 0.5', 'A third step shows how the early signal can fade.']],
    checks: [['What is the final toy state?', '0.5', '2', '0', 'The recurrence gives 2, then 1, then 0.5.'], ['When is future context a problem?', 'When the deployed task must predict before future inputs arrive', 'Whenever a dataset contains more than one row', 'Only when the model has no parameters', 'Evaluation must match what information will actually be available at prediction time.']],
    task: 'Run the toy recurrence on [0, 0, 2]. Compare the final state with the original order.', hint: 'Start again at zero; do not carry state from the first experiment.', solution: 'The states are 0, 0, 2. The final state is 2 rather than 0.5, demonstrating order dependence.' },
  { number: 17, slug: 'generative-recurrent-networks', module: 'language-and-representation', title: 'Generating sequences with recurrent networks',
    summary: 'Follow a next-token generation loop and explain the effect of temperature on sampling.',
    example: 'A model sees “delivery is” and gives candidate probabilities late 0.6, arriving 0.3, complete 0.1. Sampling can choose any candidate with nonzero probability. After choosing a token, the model updates its state and predicts again. Greedy decoding always chooses the current largest probability.',
    application: 'This is a clear way to understand autoregressive generation before moving to Transformers. It can generate text or other sequences, provided the training objective and representation fit the task.',
    limitation: 'Plausible continuations can be false. Temperature changes relative sampling preferences; it does not check sources. During training, teacher forcing provides reference tokens that may differ from the model’s own generated history at inference.',
    term: ['autoregressive-generation', 'Producing a sequence one element at a time, conditioning each new prediction on the elements already available.'],
    steps: [['Prompt and state', 'Read delivery is and form the current recurrent state.'], ['Candidate scores', 'The vocabulary contains several possible next tokens.'], ['Choose a token', 'Greedy decoding picks the top score; sampling can choose alternatives.'], ['Feed it back', 'Append the chosen token and repeat until an explicit stopping rule.']],
    checks: [['What must happen after a sampled token is selected?', 'It becomes part of the context for the next prediction', 'The entire sequence becomes guaranteed correct', 'The model must restart with an empty context', 'Generation is a sequence of conditional decisions.'], ['Does lower temperature verify facts?', 'No; it changes the sampling distribution', 'Yes; the top token is always true', 'Yes; it retrieves approved documents automatically', 'Sampling settings do not add evidence or an independent verifier.']],
    task: 'For scores [2, 1, 0], compare the order of candidates at temperatures 0.5 and 2. What changes and what stays the same?', hint: 'Temperature divides logits before softmax; use a positive temperature.', solution: 'The ranking remains first, second, third. At 0.5 the distribution is sharper; at 2 it is flatter. The probability gap changes, but the model does not gain new knowledge.' },
  { number: 18, slug: 'transformers-and-bert', module: 'language-and-representation', title: 'Attention, Transformers, and BERT',
    summary: 'Distinguish an encoder’s contextual representation from a causal decoder’s next-token prediction.',
    example: 'In “the bank beside the river”, attention lets a representation of “bank” use other token information. A BERT-style encoder can use context on both sides for a masked-token task. A causal decoder cannot attend to future tokens while predicting the next token.',
    application: 'Choose an architecture and objective for the job: encoding text for classification or retrieval differs from generating a continuation. Model names are less useful than knowing the information each output can access.',
    limitation: 'Attention weights show one computation, not a complete explanation of a model’s conclusion. A bidirectional encoder should not be evaluated as though it were a causal next-token generator.',
    term: ['causal-mask', 'A restriction that prevents a sequence position from using information from later positions during attention.'],
    steps: [['Tokens and positions', 'Represent both token identity and position information.'], ['Context interaction', 'Attention combines information according to learned queries, keys and values.'], ['Apply the mask', 'A causal decoder hides future positions; a bidirectional encoder uses both sides.'], ['Task output', 'An encoder can support labels or retrieval; a decoder can predict a continuation.']],
    checks: [['What does a causal attention mask prevent?', 'Using future token positions', 'Using any earlier token', 'Learning any model parameters', 'The mask preserves the information boundary required by next-token prediction.'], ['Which is a typical BERT pretraining task?', 'Predicting masked tokens from surrounding context', 'Predicting future pixels from a camera stream only', 'Sorting documents alphabetically without training', 'Masked-token learning uses bidirectional context around hidden token positions.']],
    task: 'Draw the allowed attention positions for a three-token causal sequence. Explain the difference for a bidirectional encoder.', hint: 'Position one can see itself; position two can also see position one.', solution: 'Causal rows: [1,0,0], [1,1,0], [1,1,1]. A basic bidirectional encoder allows all three positions in every row, except positions masked for padding or task-specific reasons.' },
  { number: 19, slug: 'named-entity-recognition', module: 'language-and-representation', title: 'Named entity recognition and BIO tags',
    summary: 'Mark entity spans rather than whole-document topics and preserve the boundaries of multiword names.',
    example: 'For “Maya joined North Star Ltd”, an example annotation is Maya/B-PER, joined/O, North/B-ORG, Star/I-ORG, Ltd/I-ORG. B marks the beginning, I continues the same entity, and O is outside. A single word’s spelling is not enough to decide its type in every context.',
    application: 'NER can prepare fields from contracts, messages, or documents for a person to verify. A team can assess both whether the span boundaries are right and whether the category is right.',
    limitation: 'Entity extraction does not establish that a statement is true or that an extracted organisation is the correct record in a database. Tokenization and multiword boundaries need explicit handling.',
    term: ['named-entity-recognition', 'Identifying spans of text that refer to categories such as people, organisations, places, or dates.'],
    steps: [['Input sentence', 'Maya joined North Star Ltd.'], ['Token labels', 'Each token receives a category and a boundary marker.'], ['Combine spans', 'North, Star and Ltd become one organisation span.'], ['Verify extraction', 'Compare both the entity type and exact boundaries with a reference.']],
    checks: [['Why is Star tagged I-ORG in the example?', 'It continues the organisation begun at North', 'Every capitalised word must begin a new person', 'It is outside all entities', 'BIO tags distinguish the start and continuation of a multiword span.'], ['What does extracting a company name establish?', 'That a span was labelled as a company reference', 'That every claim about that company is true', 'That the correct customer database record was selected', 'Extraction, factual verification, and entity linking are separate tasks.']],
    task: 'Tag “Ravi visited New Delhi” using PER, LOC, and O with BIO boundaries.', hint: 'New Delhi is one location with two tokens.', solution: 'Ravi/B-PER visited/O New/B-LOC Delhi/I-LOC. Different annotation guidelines can use different categories, so define them before training or scoring.' },
  { number: 20, slug: 'llms-and-few-shot-prompting', module: 'language-and-representation', title: 'Large language models and few-shot tasks',
    summary: 'Use examples to specify a task, then evaluate the output separately from how fluent it sounds.',
    example: 'You want short requests classified as billing, delivery, or other. Give a model a clear instruction, two labelled examples, and a new request. The examples help establish the desired mapping and format. The model’s weights do not change merely because examples appear in the prompt.',
    application: 'Teams can prototype drafting and classification workflows quickly, but should keep a representative evaluation set and compare a simple baseline. For source-based answers, provide retrieval and review as separate steps.',
    limitation: 'Few-shot prompting is not parameter fine-tuning. Prompt wording, example order, ambiguity, and supplied context can affect results. A low language-modelling loss does not guarantee task safety or factual accuracy.',
    term: ['few-shot-prompting', 'Providing a small number of examples within a prompt to show the task or output pattern at inference time.'],
    steps: [['Define the task', 'Specify the allowed categories and what to do with ambiguous requests.'], ['Show examples', 'Provide representative input/output pairs without leaking test answers.'], ['Run held-out cases', 'Ask for predictions on requests not used to design the prompt.'], ['Review errors', 'Count wrong categories and inspect ambiguous or unsupported outputs.']],
    checks: [['Do in-prompt examples normally update model weights?', 'No; they condition the current inference', 'Yes; they always fine-tune the whole model', 'Yes; they permanently rewrite the training set', 'Few-shot prompting supplies context, while fine-tuning performs parameter updates.'], ['Which evaluation is more useful?', 'Testing a fixed prompt on held-out representative requests', 'Only showing the best response from repeated trials', 'Checking whether every output sounds confident', 'A consistent evaluation exposes failure patterns that selected demonstrations can hide.']],
    task: 'Write a classification instruction with allowed labels and a rule for ambiguity. Give one example, then invent a test request that challenges the rule.', hint: 'Decide whether mixed-topic requests get one label, several labels, or escalation.', solution: 'Example rule: return billing, delivery, or other; use other for mixed or unclear requests. Example: “Where is my parcel?” → delivery. Challenge: “My parcel is late and I was charged twice” → other under this rule.' },
  { number: 21, slug: 'genetic-algorithms', module: 'search-and-agents', title: 'Genetic algorithms: search over candidates',
    summary: 'Trace population, fitness, selection, crossover, and mutation without assuming the best result is guaranteed.',
    example: 'A toy packing problem has items A: value 6, weight 4; B: value 4, weight 2; C: value 5, weight 3, and capacity 5. Candidate [0,1,1] selects B and C, weighs 5, and has value 9. Candidate [1,1,0] weighs 6 and is invalid unless the scoring scheme explicitly penalises or repairs it.',
    application: 'Evolutionary search can explore schedules, configurations, or layouts when the search space is difficult. The representation and fitness function must express the actual operational constraints.',
    limitation: 'Crossover can produce invalid candidates, and mutation does not guarantee escape from every local optimum. Always define feasibility, a comparison baseline, and a stopping budget.',
    term: ['fitness-function', 'A rule for scoring candidate solutions during a search, with a clearly stated direction and treatment of constraints.'],
    steps: [['Candidate population', 'Represent selected items as bit vectors.'], ['Score and constrain', 'B + C has weight 5 and value 9; overweight combinations are not acceptable.'], ['Select and vary', 'Prefer useful candidates, recombine choices, and occasionally mutate them.'], ['Check and stop', 'Keep the best feasible result found within the chosen budget.']],
    checks: [['Which candidate is feasible under capacity 5?', '[0,1,1]', '[1,1,0]', '[1,1,1]', 'B and C weigh 2 + 3 = 5; the other options exceed capacity.'], ['Does crossover always preserve feasibility?', 'No; the representation or an explicit check must handle constraints', 'Yes; inherited choices are automatically valid together', 'Yes; a fitness score removes all constraints', 'Two valid parents can produce an invalid combination.']],
    task: 'Enumerate the eight bit-vector candidates for this three-item problem. Find the best feasible value, then compare what an evolutionary method would need to report.', hint: 'There are only 2³ candidates, so exhaustive search is a useful baseline here.', solution: 'Feasible values: 000→0, 100→6, 010→4, 001→5, 011→9. The other combinations exceed capacity. Best is 011 with value 9. An evolutionary run should report feasibility, value, and search budget; it need not find the optimum every time.' },
  { number: 22, slug: 'reinforcement-learning', module: 'search-and-agents', title: 'Reinforcement learning: states, actions, and rewards',
    summary: 'Distinguish learning from interaction from supervised labels and compute a simple value update.',
    example: 'An agent in a small grid chooses right, receives reward 1, and reaches a state whose best estimated future value is 4. With discount 0.9, its target is 1 + 0.9 × 4 = 4.6. If the old action value is 2 and the learning rate is 0.5, a Q-learning update gives 2 + 0.5 × (4.6 − 2) = 3.3.',
    application: 'RL can study sequential control and allocation where one action changes what happens next. A simulator gives a place to explore choices before considering any real-world experiment.',
    limitation: 'Reward is a chosen proxy for the desired outcome. An agent can exploit that proxy, and simulation performance may not transfer. Terminal transitions do not bootstrap future value beyond the terminal state.',
    term: ['reinforcement-learning', 'Learning a policy through interactions where actions lead to new states and rewards.'],
    steps: [['State and action', 'Observe the current state and choose an action.'], ['Reward and next state', 'Receive reward 1 and observe the next state.'], ['Target: 4.6', 'Combine immediate reward with discounted future value.'], ['Update: 3.3', 'Move the old estimate partway toward the target, then repeat.']],
    checks: [['What is the worked updated action value?', '3.3', '4.6', '2', 'The update moves halfway from 2 toward target 4.6.'], ['Why test reward design?', 'Optimising a proxy can produce behaviour that misses the real goal', 'Rewards automatically represent every human preference', 'A simulator proves deployment is safe', 'The objective and environment constrain what the agent learns, sometimes in unintended ways.']],
    task: 'Repeat the update for a terminal transition with reward 1, old value 2, and rate 0.5.', hint: 'There is no discounted future value after a terminal transition.', solution: 'Target = 1. New value = 2 + 0.5 × (1 − 2) = 1.5. Treating the terminal state as if it still had value 4 would change the learning target incorrectly.' },
  { number: 23, slug: 'multi-agent-systems', module: 'search-and-agents', title: 'Multi-agent systems and coordination',
    summary: 'Explain how local decisions create collective behaviour and identify where coordination is needed.',
    example: 'Two warehouse robots plan to enter the same narrow aisle from opposite ends. Each shortest-path plan may be reasonable alone, yet both plans together conflict. A reservation rule can grant one robot access while the other waits. The shared outcome depends on interaction, not only the quality of each individual plan.',
    application: 'Agent-based models can explore traffic, crowds, ecosystems, or teams of software agents. They help test how local rules, communication, and shared resources affect overall behaviour.',
    limitation: 'More agents do not automatically improve results. Communication costs, conflicting goals, deadlocks, and shared mistakes can dominate. A simulation demonstrates assumptions, not a verified forecast of a real organisation.',
    term: ['multi-agent-system', 'A system containing multiple interacting decision-making entities whose actions affect one another or a shared environment.'],
    steps: [['Local observations', 'Each robot sees its own position, goal, and available information.'], ['Proposed actions', 'Both independently request the narrow aisle.'], ['Coordinate access', 'A reservation rule resolves the shared-resource conflict.'], ['Measure the group', 'Evaluate throughput, waiting time, fairness, and collision prevention together.']],
    checks: [['Why can individually good plans conflict?', 'Agents share resources and affect each other’s available actions', 'Every agent always has identical goals', 'An additional agent removes all constraints', 'Interaction creates constraints that may not appear in an individual planning problem.'], ['Which metric is insufficient on its own?', 'The travel time of the single fastest robot', 'Group throughput together with collision checks', 'Waiting-time distribution together with safety outcomes', 'A single best-case agent can hide poor or unsafe collective behaviour.']],
    task: 'Write an aisle reservation rule and one case where a naive first-come rule could cause a problem.', hint: 'Consider a failed robot, a request that never expires, and repeated requests from one participant.', solution: 'Grant one time-bounded reservation; require release or expiry before the next grant; record waiting requests. A non-expiring reservation from a failed robot blocks the aisle. Repeated requests may also need fairness rules.' },
  { number: 24, slug: 'responsible-ai', module: 'responsible-practice', title: 'Responsible AI as an operating practice',
    summary: 'Turn broad principles into concrete checks for data, people, decisions, and ongoing accountability.',
    example: 'A support-routing tool correctly routes 90 of 100 requests overall. But it routes only 10 of 20 requests in one language correctly and all 80 requests in another language correctly. The overall 90% hides a 50% versus 100% gap. A release decision needs more context than the aggregate score.',
    application: 'Leaders define acceptable outcomes and accountability; team members identify workflow failures; architects handle access and data boundaries; delivery and operations maintain evaluation, incident response, and review processes.',
    limitation: 'No single fairness metric settles every situation. Group definitions, sample sizes, harms, privacy, accessibility, and legal context need careful consideration. A checklist is an aid to judgment, not a compliance certificate.',
    term: ['disaggregated-evaluation', 'Evaluating performance across relevant groups or conditions instead of relying only on an overall average.'],
    steps: [['Define affected people', 'Identify users and people affected by the system’s decisions.'], ['Measure by context', 'Compare overall and group-level outcomes with sample sizes.'], ['Assign accountability', 'Name who can review, override, correct, and stop the workflow.'], ['Monitor after release', 'Recheck source changes, errors, accessibility, and consequences over time.']],
    checks: [['What does the overall 90% conceal?', 'A substantial difference between language groups', 'Proof that the smaller group has no useful data', 'A guarantee that every individual gets the same service', 'Disaggregating the result reveals 10/20 versus 80/80 performance.'], ['Which action makes accountability concrete?', 'Naming an owner and a process for review, correction, and stopping', 'Adding the word responsible to the product title', 'Assuming the model vendor handles every operational decision', 'Responsibilities must be assigned in the actual workflow, not only described as principles.']],
    task: 'Create a four-line release note: intended use, affected people, evidence required, and a pause condition for the routing tool.', hint: 'Include language-specific performance and a human route for unresolved requests.', solution: 'Use: assist support routing. People: requesters and support teams across supported languages. Evidence: representative tests, group counts, error review and accessible fallback. Pause: a defined increase in misrouting or inability to serve a supported group, escalated to a named owner.' },
  { number: 25, slug: 'multimodal-clip-and-generation', module: 'multimodal-extension', title: 'Multimodal learning: CLIP and image generation',
    summary: 'Explain shared image-text representations and distinguish matching from generating an image.',
    example: 'A CLIP-style model encodes an image and candidate descriptions such as “a red delivery van” and “a blue bicycle”. Similarity scores rank the descriptions for that image. Changing the candidate list or wording can change the result. This comparison does not itself generate a new picture.',
    application: 'Multimodal representations can support image search and zero-shot classification experiments. Generative systems add a process that creates an image, which needs separate evaluation for quality, diversity, and fitness for use.',
    limitation: 'Similarity is conditional on the model, prompt wording, and candidates. It is not a calibrated probability of truth. CLIP-guided VQGAN and later image-generation systems use different mechanisms; historical examples are not current model rankings.',
    term: ['contrastive-learning', 'Learning representations by making matched examples more compatible than selected mismatched examples.'],
    steps: [['Image and text', 'Supply an image and several candidate descriptions.'], ['Separate encoders', 'Map each modality into a comparable representation space.'], ['Compare alignment', 'Compute similarities between the image and text representations.'], ['Rank and evaluate', 'Inspect how candidate wording and unfamiliar images affect the result.']],
    checks: [['What does CLIP-style matching directly return?', 'Compatibility scores between image and text representations', 'A newly generated image in every case', 'Verified facts about the image’s origin', 'Matching and generation are separate operations, even when one system combines them.'], ['Why test several candidate descriptions?', 'Wording and candidate choice can affect rankings', 'The first prompt is always objectively best', 'More candidates guarantee a correct answer', 'Evaluation should examine the actual prompt and candidate conditions used in the application.']],
    task: 'Design an image-search test with three descriptions, one ambiguous image, and a rule for when to ask a person to review the result.', hint: 'Do not turn a small score gap into a confident factual statement.', solution: 'Use distinct candidate descriptions and a deliberately ambiguous scene. Record the rankings and sensitivity to rewording. Route ambiguous or unstable matches for review; validate any threshold on representative examples rather than inventing a universal score cutoff.' },
]

const applicationChecks: CompleteAiGuide['checks'][number][] = [
  ['A fixed expense limit changes from 100 to 80. What should change first?', 'The explicit rule and its boundary tests', 'The label of every past customer message', 'The number of words in a generated reply', 'A policy threshold is an explicit requirement; update its implementation and tests.'],
  ['What does backward inference start from?', 'A goal or conclusion whose supporting conditions are investigated', 'Every possible output at random', 'An assumption that all missing facts are true', 'Backward reasoning asks which rules and facts would support a proposed goal.'],
  ['What happens when the bias increases with weights fixed?', 'The decision boundary shifts', 'All input values are rewritten', 'The classifier becomes nonlinear automatically', 'Bias changes the score offset; a thresholded linear score still has a linear boundary.'],
  ['Why add nonlinear activations between linear layers?', 'Without them, the composed mapping remains linear or affine', 'They guarantee zero test error', 'They remove every parameter from the model', 'Stacking affine operations alone still yields an affine operation.'],
  ['Which result is consistent with overfitting?', 'Training loss falls while validation loss rises', 'Both losses are always identical by definition', 'The model has no training examples', 'The pattern suggests fitting training-specific details rather than improving generalisation.'],
  ['Which RGB value corresponds to BGR (10, 20, 240)?', '(240, 20, 10)', '(20, 240, 10)', '(10, 20, 240)', 'Swap red and blue while keeping the green channel in the middle.'],
  ['What does max pooling over [1, 4, 2, 3] return?', '4', '2.5', '10', 'Max pooling retains the largest value in the selected neighbourhood.'],
  ['What is a sensible first transfer-learning baseline?', 'Train a new head with the pretrained backbone frozen', 'Assume the old class names already match the new task', 'Choose settings using the final test set repeatedly', 'A frozen backbone helps establish a baseline before a more expensive adaptation.'],
  ['What must be checked before using reconstruction error for anomaly review?', 'Whether error separates useful cases under representative conditions', 'Whether every reconstructed file has a short name', 'Whether the decoder always returns exactly one number', 'The operational meaning of an error score needs evaluation, not assumption.'],
  ['Why inspect several generated samples?', 'A good single image can hide poor diversity or inconsistent quality', 'Only the first sample has any statistical meaning', 'Every sample proves ownership of the training data', 'A distribution of outputs matters; one selected success is insufficient.'],
  ['A detector draws two boxes around one real object. What may result?', 'A duplicate false-positive detection under the matching rule', 'Two new ground-truth objects', 'Perfect counting automatically', 'Evaluation normally matches object instances; extra unmatched predictions can count as errors.'],
  ['What distinguishes instance from semantic segmentation?', 'Instance segmentation can separate different objects of the same category', 'Semantic segmentation never uses pixels', 'Instance segmentation only gives a whole-image label', 'Category labels alone need not distinguish separate object instances.'],
  ['Which text feature preserves a short word-order pattern?', 'An n-gram such as “not approved”', 'Only a document’s character count', 'Sorting all words alphabetically', 'N-grams represent adjacent token sequences rather than isolated term counts.'],
  ['Which description best fits GloVe training?', 'Learning vectors from word co-occurrence statistics', 'Assigning coordinates from alphabetical position', 'Guaranteeing unbiased semantic meanings', 'GloVe uses aggregate co-occurrence relationships in its embedding objective.'],
  ['In skip-gram, what serves as input in the worked window?', 'The centre word “useful”', 'Only the sentence length', 'The document’s review score', 'Skip-gram uses a centre word to predict context words.'],
  ['What do LSTM gates control?', 'How information is added, retained, and exposed in memory', 'The number of characters in the source file only', 'Whether all future inputs are already known', 'Learned gating changes how recurrent information flows through the memory state.'],
  ['What does teacher forcing supply during training?', 'Reference sequence tokens as previous-step inputs', 'A guarantee that generated sequences cannot drift', 'The final test answers during deployment', 'Training may condition on reference history, while inference conditions on generated history.'],
  ['Why include position information in a Transformer?', 'Attention by itself does not encode sequence order in the required way', 'All words must have the same position', 'It removes the need for training data', 'Position information makes sequence arrangement available to the model.'],
  ['Which tag begins the location in “New Delhi”?', 'B-LOC on New', 'I-LOC on New with no preceding location', 'O on both tokens', 'The first token begins the span and the next token continues it.'],
  ['When should prompt changes be compared?', 'On a consistent evaluation set that was not used to supply answers', 'Only after selecting each prompt’s best-looking response', 'By counting punctuation marks alone', 'Consistent held-out cases reveal whether a change actually improves the task.'],
  ['Why compare a genetic algorithm with exhaustive search on three bits?', 'There are only eight candidates, so the optimum is easy to verify', 'Genetic algorithms cannot use bits', 'Exhaustive search always scales well to every real problem', 'A small exact baseline helps validate scoring and constraints without implying scalability.'],
  ['What is the role of a discount factor?', 'It controls the contribution of future rewards to the return', 'It directly sets the amount of available memory', 'It guarantees exploration of every action', 'Discounting changes the weight of delayed outcomes in the learning objective.'],
  ['Why might reservations need expiration?', 'A failed agent could otherwise block a shared resource indefinitely', 'Time limits make every plan optimal', 'Expired requests never require logging', 'Coordination must handle failures, not only successful cooperative agents.'],
  ['Why report sample sizes beside group scores?', 'Small groups can produce unstable estimates and hide uncertainty', 'A percentage is exact evidence about every future person', 'Large groups always make ethical decisions unnecessary', 'Counts help readers judge what the observed performance can support.'],
  ['What does contrastive image-text training compare?', 'Matched image-text pairs with selected mismatched pairs', 'Only the image file extensions', 'A guaranteed true caption with every possible fact', 'The objective encourages compatibility of paired representations, not factual verification of all descriptions.'],
]
completeAiGuides.forEach((guide, index) => guide.checks.push(applicationChecks[index]))
